        "\u0176\u002e\u0076\u0091\u0160\u0174\u0000\u0000\u0000\u0000\u0183\u0000\u0155\u0000\u0000\u0000\u0196\u0000\u0000\u0000\u0000\u012e\u0000\u0000\u0000\u0000\u0000\u00bb\u0000\u0000\u0000\u0000" +
        "\u0000\u0000\u0000\u0126\u00b1\u0000\u0000\u0188\u0000\u0000\u0000\u0000\u00b1\u0061\u013f\u00c1\u0000\u0000\u0000\u0000\u0063\u003b\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0000" +
        "\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0000\u0005\u0147\u00dd\u0000\u0000\u0073\u0006\u00aa\u0151\u0048\u0189\u00a9\u0003\u0151\u00c9\u00c1\u0015\u0086\u0000\u00a9\u0162"

internal fun threadComposerGeneratedPinyin(char: Char): String? {
    val code = char.code
    if (code < ThreadComposerPinyinBasicStart || code > ThreadComposerPinyinBasicEnd) return null
    val index = ThreadComposerPinyinBasicIndexes[code - ThreadComposerPinyinBasicStart].code
    return ThreadComposerPinyinSyllables.getOrNull(index)?.takeIf { it.isNotBlank() }
}
